#!/usr/bin/env bash
# ENSAYO del respaldo lógico y de la restauración (sobre bases DESECHABLES de un PostgreSQL de PRUEBA; nunca una base hospedada). Demuestra lo que se hará con nexa-demo ANTES de la migración 29:
#   1. un respaldo lógico (pg_dump -Fc de «public» y «supabase_migrations», con permisos) de una base con las 28 migraciones y datos;  2. se valida SIN confiar en el archivo: pg_restore --list, SHA-256 y restauración real en una base aparte;
#   3. la base restaurada queda sana (catálogo de la 28 en solo lectura, 67 tablas, historial de 28, la 29 ausente, mismos datos);  4. tras aplicar la 29 y registrar una certificación, restaurar el respaldo ANTERIOR pierde esa operación
#   (el estado que el chequeo previo y la conciliación con Digifact existen para cubrir: la restauración NUNCA recertifica) y la reversión de la 29 con datos se rechaza.
# Uso: PSQL_BIN=psql CONN='postgresql://postgres@/{DB}?host=/tmp&port=54399' bash respaldo_restauracion_29.sh
set -u
RAIZ="$(cd "$(dirname "$0")/../.." && pwd)"; cd "$RAIZ"
PSQL_BIN=${PSQL_BIN:-psql}; BIN="$(dirname "$(command -v "$PSQL_BIN")")"; PGDUMP="$BIN/pg_dump"; PGRESTORE="$BIN/pg_restore"; [ -x "$PGDUMP" ] || { PGDUMP=pg_dump; PGRESTORE=pg_restore; }
CONN=${CONN:?define CONN (con la marca DB entre llaves)}; M=supabase/migrations/20261114000100_fel_digifact_operaciones.sql; MARCA="{DB}"; T="$(mktemp -d)"; trap 'rm -rf -- "$T"' EXIT
Q() { local db="$1"; shift; "$PSQL_BIN" "${CONN//$MARCA/$db}" -v ON_ERROR_STOP=1 -q -X "$@"; }
U() { echo "${CONN//$MARCA/$1}"; }
ok() { echo "OK respaldo-29: $1"; }; mal() { echo "FALLO respaldo-29: $1"; FALLOS=$((FALLOS+1)); }; FALLOS=0
RO() { local db="$1" arch="$2"; printf '%s\n' '\set ON_ERROR_STOP on' 'begin transaction read only;' "\\i $arch" > "$T/ro.sql"; Q "$db" -f "$T/ro.sql" 2>&1; }   # el MISMO envoltorio de solo lectura que usa la verificación hospedada
base28() { Q postgres -c "drop database if exists $1 with (force)" -c "create database $1" >/dev/null 2>&1; Q $1 -f tools/shim_supabase.sql >/dev/null
  for f in supabase/migrations/*.sql; do case "$f" in *20261114000100*|*20261115000100*) ;; *) Q $1 -f "$f" >/dev/null 2>&1 || { echo "no se pudo aplicar $f en $1"; return 1; };; esac; done
  Q $1 -c "create schema if not exists supabase_migrations; create table if not exists supabase_migrations.schema_migrations (version text primary key, name text, statements text[]); insert into supabase_migrations.schema_migrations (version) select split_part(f, '_', 1) from unnest(string_to_array('$(ls supabase/migrations | grep -v -e 20261114000100 -e 20261115000100 | tr '\n' ' ' | sed 's/ $//')', ' ')) f on conflict do nothing" >/dev/null; }
echo "== 1. base de ORIGEN con las 28 migraciones y datos"
base28 t_r1 && ok "origen preparado (28 migraciones y su historial)" || mal "no se pudo preparar el origen"
Q t_r1 -c "insert into auth.users (id, email, email_confirmed_at) values ('30000000-0000-0000-0000-0000000000a1', 'actor@prueba.local', now())" -c "insert into public.empresas (id, nombre_comercial, razon_social, nit, regimen_id) select '10000000-0000-0000-0000-0000000000a1', 'Empresa R', 'Empresa R S.A.', '9900001-1', id from public.regimenes_fiscales where codigo = 'general'" \
  -c "insert into public.documentos (id, empresa_id, numero_borrador, estado_preparacion) select ('20000000-0000-0000-0000-' || lpad(n::text, 12, '0'))::uuid, '10000000-0000-0000-0000-0000000000a1', n, 'borrador' from generate_series(1,3) n" >/dev/null 2>&1 && ok "datos de prueba (1 empresa, 3 documentos)" || mal "no se pudieron insertar los datos"
echo "== 2. respaldo lógico y su validación (sin confiar en el archivo)"
"$PGDUMP" "$(U t_r1)" -Fc --schema=public --schema=supabase_migrations -f "$T/respaldo.dump" 2>"$T/dump.err" && [ -s "$T/respaldo.dump" ] && ok "pg_dump -Fc de public y supabase_migrations (incluye permisos)" || { mal "pg_dump falló: $(head -2 "$T/dump.err")"; }
SHA="$(sha256sum "$T/respaldo.dump" | cut -d' ' -f1)"; [ ${#SHA} = 64 ] && ok "SHA-256 del archivo registrado (${SHA:0:12}…): se compara al restaurar" || mal "sin SHA-256"
"$PGRESTORE" --list "$T/respaldo.dump" > "$T/lista.txt" 2>&1 && grep -q "TABLE DATA public empresas" "$T/lista.txt" && grep -q "TABLE DATA supabase_migrations schema_migrations" "$T/lista.txt" && ok "pg_restore --list lee el archivo y contiene los datos de empresas y del historial de migraciones" || mal "el archivo no se puede listar o le faltan datos"
echo "== 3. restauración real en una base APARTE (nunca sobre el origen) y comprobación"
Q postgres -c "drop database if exists t_r2 with (force)" -c "create database t_r2" >/dev/null 2>&1; Q t_r2 -f tools/shim_supabase.sql >/dev/null
Q t_r1 -c "\\copy (select * from auth.users) to '$T/users.csv' csv" >/dev/null 2>&1; Q t_r2 -c "\\copy auth.users from '$T/users.csv' csv" >/dev/null 2>&1   # en Supabase real los usuarios de Auth existen en el proyecto destino (nexa-demo los recrea con «aprovisionar»)
[ "$(sha256sum "$T/respaldo.dump" | cut -d' ' -f1)" = "$SHA" ] && ok "el archivo no cambió desde que se respaldó (SHA-256 igual)" || mal "el archivo cambió"
# DESTINO LIMPIO de privilegios por defecto (documentado por Supabase): las tablas restauradas heredan los permisos por defecto del destino; si no se retiran antes, anon/authenticated/service_role quedarían con acceso que el origen no tenía
Q t_r2 -c "alter default privileges in schema public revoke all on tables from anon, authenticated, service_role" -c "alter default privileges in schema public revoke all on sequences from anon, authenticated, service_role" -c "alter default privileges in schema public revoke execute on functions from anon, authenticated, service_role" >/dev/null 2>&1
grep -v " SCHEMA - public " "$T/lista.txt" > "$T/lista_sin_schema.txt"   # la base destino ya trae el esquema public (en Supabase también): se restaura SU CONTENIDO, no se vuelve a crear el esquema
"$PGRESTORE" -d "$(U t_r2)" --no-owner --exit-on-error --single-transaction -L "$T/lista_sin_schema.txt" "$T/respaldo.dump" 2>"$T/restore.err" && ok "pg_restore en una sola transacción terminó sin errores" || mal "pg_restore falló: $(grep -m2 -i error "$T/restore.err")"
N1="$(Q t_r1 -tA -c "select (select count(*) from public.empresas) || '/' || (select count(*) from public.documentos) || '/' || (select count(*) from supabase_migrations.schema_migrations)")"; N2="$(Q t_r2 -tA -c "select (select count(*) from public.empresas) || '/' || (select count(*) from public.documentos) || '/' || (select count(*) from supabase_migrations.schema_migrations)")"
[ "$N1" = "$N2" ] && [ "$N1" = "1/3/28" ] && ok "la base restaurada tiene los MISMOS datos (empresas/documentos/migraciones = $N2)" || mal "los datos no coinciden: origen $N1, restaurada $N2"
{ RO t_r2 docs/migracion-28/verificacion-posterior-28.sql > "$T/cat28.txt"; grep -q "VERIFICACION POSTERIOR 28 OK" "$T/cat28.txt"; } && ok "la base restaurada pasa el catálogo de la 28 (67 tablas, políticas, funciones y privilegios), en una transacción de solo lectura" || mal "la base restaurada NO pasa el catálogo de la 28: $(grep -m1 ERROR "$T/cat28.txt")"
[ "$(Q t_r2 -tA -c "select to_regclass('public.digifact_operaciones') is null")" = "t" ] && ok "la 29 sigue ausente en la restaurada" || mal "la restaurada ya tiene la 29"
echo "== 4. después de aplicar la 29 y registrar una certificación: restaurar el respaldo ANTERIOR pierde esa operación (por eso existe el chequeo previo + conciliación)"
Q t_r1 -f $M >/dev/null 2>&1 && ok "29 aplicada en el origen" || mal "no se aplicó la 29"
Q t_r1 -c "insert into public.digifact_operaciones (id, empresa_id, documento_id, referencia, hash, huella_emisor, fecha_emision, establecimiento, total, estado, creada_ms, actualizada_ms, actor_id, intento_del_documento) values (gen_random_uuid(), '10000000-0000-0000-0000-0000000000a1', '20000000-0000-0000-0000-000000000001', gen_random_uuid(), repeat('a', 64), '0123456789abcdef', '2026-11-22', 1, '112.00', 'preparada', 1000, 1000, '30000000-0000-0000-0000-0000000000a1', 0)" \
  -c "update public.digifact_operaciones set estado = 'enviando', actualizada_ms = 2000" -c "update public.digifact_operaciones set estado = 'certificada', actualizada_ms = 3000, resultado = '{\"autorizacion\":\"AAAAAAAA-0000-0000-0000-00000000AA01\",\"serie\":\"A001\",\"numero\":\"5\"}'" >/dev/null 2>&1 && ok "operación certificada registrada en el origen" || mal "no se pudo registrar la operación"
[ "$(Q t_r1 -tA -c "select count(*) from public.digifact_operaciones")" = "1" ] && [ "$(Q t_r2 -tA -c "select to_regclass('public.digifact_operaciones') is null")" = "t" ] && ok "el respaldo anterior NO contiene la operación: restaurarlo la perdería (Digifact sí la conserva); la restauración jamás recertifica: se concilia" || mal "estado inesperado"
Q t_r1 -f docs/migracion-29/reversion-29.sql 2>&1 | grep -q "REVERSIÓN 29 RECHAZADA" && [ "$(Q t_r1 -tA -c "select count(*) from public.digifact_operaciones")" = "1" ] && ok "con una operación registrada la reversión se RECHAZA y no borra nada (la salida es corregir hacia adelante o restaurar y conciliar)" || mal "la reversión no se rechazó con datos"
echo "== 5. el respaldo posterior a la 29 sí la conserva"
"$PGDUMP" "$(U t_r1)" -Fc --schema=public --schema=supabase_migrations -f "$T/respaldo29.dump" 2>/dev/null && "$PGRESTORE" --list "$T/respaldo29.dump" 2>/dev/null | grep -q "TABLE DATA public digifact_operaciones" && ok "un respaldo hecho después de la 29 incluye digifact_operaciones y digifact_artefactos" || mal "el respaldo posterior no incluye las tablas de la 29"
[ "$FALLOS" = 0 ] && echo "RESPALDO Y RESTAURACIÓN 29 OK" || { echo "$FALLOS FALLO(S)"; exit 1; }
